      "value": "fetal_growth_and_placental_efficiency",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00027",
          "quote": "We previously showed that 10-week paternal RF-EMR exposure predisposes male offspring to impaired glucose metabolism in a mouse model (Yan et al., 2022). However, whether chronic paternal Wi-Fi exposure influences intrauterine development through sperm-mediated epigenetic mechanisms remains to be determined."
        },
        {
          "block_id": "b00080",
          "quote": "Compared with the SE group, the RE group exhibited significantly lower fetal weights in both male (1316.9 ± 235 mg vs. 1425.7 ± 143 mg, p = 0.004) and female (1268.9 ± 225 mg vs. 1398.6 ± 211 mg, P = 0.0047) offspring (Table 1)."
        }
      ]
    },
    "secondary_outcomes": {
      "value": ["sperm_parameters", "histone_modifications"],
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00066",
          "quote": "The total sperm abnormality rate in the RF-EMR exposure (RE) group increased markedly to 89.51%, which was significantly higher than the 29.33% observed in the sham-exposed (SE) group (p < 0.001) (Fig. 1B)."
        },
        {
          "block_id": "b00100",
          "quote": "Compared with placentas from the same-sex SE group, male placentas in the RE group exhibited significantly increased levels of H3K27ac (p = 0.009), H3K27me3 (p < 0.001), H3K9me3 (p = 0.003), H3K9me2 (p = 0.006), and H3K4me2 (p = 0.002), whereas H3K4me3 levels did not differ significantly (p > 0.05) (Fig. 5A-B)."
        }
      ]
    },
